# Use small config for fast tests
SMALL_CONFIG = BenchmarkConfig(
    mb_config=MandelbrotConfig(max_iter=20, chunk_size=32),
    calculators=["numpy"],
    resolutions=[32, 64],
    num_runs=2,
    warmup_runs=1,
)


class TestBenchmarkResult:
    """Tests for the BenchmarkResult dataclass."""

    def test_mean_time(self):
        result = BenchmarkResult(calculator_name="test", resolution=64, times=[1.0, 2.0, 3.0])
        assert result.mean_time == pytest.approx(2.0)

    def test_std_time(self):
        result = BenchmarkResult(calculator_name="test", resolution=64, times=[2.0, 2.0, 2.0])
        assert result.std_time == pytest.approx(0.0)

    def test_min_time(self):
        result = BenchmarkResult(calculator_name="test", resolution=64, times=[3.0, 1.0, 2.0])
        assert result.min_time == pytest.approx(1.0)


class TestBenchmarkRunner:
    """Tests for the BenchmarkRunner class."""

    def test_returns_results_for_each_calculator_resolution_pair(self):
        runner = BenchmarkRunner(SMALL_CONFIG)
        results = runner.run()
        # 1 calculator × 2 resolutions = 2 results
        assert len(results) == 2

    def test_result_has_correct_calculator_name(self):
        runner = BenchmarkRunner(SMALL_CONFIG)
        results = runner.run()
        assert all(r.calculator_name == "NumpyCalculator" for r in results)

    def test_result_has_correct_resolutions(self):
        runner = BenchmarkRunner(SMALL_CONFIG)
        results = runner.run()
        resolutions = [r.resolution for r in results]
        assert resolutions == [32, 64]

    def test_result_has_correct_number_of_timed_runs(self):
        runner = BenchmarkRunner(SMALL_CONFIG)
        results = runner.run()
        assert all(len(r.times) == 2 for r in results)

    def test_times_are_positive(self):
        runner = BenchmarkRunner(SMALL_CONFIG)
        results = runner.run()
        for r in results:
            assert all(t > 0 for t in r.times)

    def test_skips_higher_resolutions_when_slow(self):
        """Verify that resolutions are skipped when mean_time > 10s."""
        # Use native calculator with a resolution large enough to be slow,
        # but mock isn't needed — just verify the logic with a threshold config
        config = BenchmarkConfig(
            mb_config=MandelbrotConfig(max_iter=20, chunk_size=32),
            calculators=["numpy"],
            resolutions=[32, 64, 128],
            num_runs=1,
            warmup_runs=0,
        )
        runner = BenchmarkRunner(config)
        results = runner.run()
        # At these tiny sizes, nothing exceeds 10s, so all resolutions run
        assert len(results) == 3

    def test_multiple_calculators(self):
        config = BenchmarkConfig(
            mb_config=MandelbrotConfig(max_iter=20, chunk_size=32),
            calculators=["numpy", "numba"],
            resolutions=[32],
            num_runs=1,
            warmup_runs=1,
        )
        runner = BenchmarkRunner(config)
        results = runner.run()
        assert len(results) == 2
        names = {r.calculator_name for r in results}
        assert names == {"NumpyCalculator", "NumbaCalculator"}

    def test_results_stored_on_instance(self):
        runner = BenchmarkRunner(SMALL_CONFIG)
        results = runner.run()
        assert runner.results is results
